-- ============================================================================
-- T018 — 전남·광주 통합(46·29 → 12) 매핑표 **데이터 스냅샷**
--
--   성격    : **열람·리뷰용 데이터 덤프.** 정본(正本) 생성은
--             scripts/postgis/build_sido_remap.sql 이며 이 파일은 그 산출 결과를
--             그대로 떠낸 것이다. 두 파일이 어긋나면 build_sido_remap.sql 이 우선한다.
--   목적    : 안 B 담당자·리뷰어가 **DB 를 갖추고 스크립트를 돌리기 전에도**
--             매핑 내용을 그대로 읽을 수 있게 한다(검수 지적 Fix 2).
--   추출    : 2026-08-10, 로컬 PostGIS 컨테이너 server-postgis-1 (DB cuvia).
--             SELECT 만 사용했고 DB 를 일절 변경하지 않았다.
--   행수    : lawd_sido_remap 623행 (src='lawd_dong' 622 + src='admin_boundary' 1)
--             lawd_ri_remap_exception 4행
--             ※ 검수 지적문의 "622행"은 src='lawd_dong' 게이트 행수를 가리킨다.
--               admin_boundary 보강분 1행을 더한 테이블 전량은 623행이다.
--
--   실행(선택): 이 파일 단독으로도 적재 가능하다. 멱등하게 동작하도록
--               CREATE TABLE IF NOT EXISTS + ON CONFLICT DO NOTHING 을 쓴다.
--                 unset PGOPTIONS
--                 docker exec -i server-postgis-1 psql -U cuvia -d cuvia -v ON_ERROR_STOP=1 \
--                   < scripts/postgis/lawd_sido_remap_data.sql
--               이미 build_sido_remap.sql 로 만든 표가 있으면 아무것도 바꾸지 않는다.
--
--   주의    : 이 표는 **응답 경계 치환 전용**이다. 안 A 에서 DB 내부값은 46/29 로 남는다.
--             DB 를 직접 조회하면 API 응답과 다른 코드가 보인다 — 결함이 아니라 안 A 의 정의다.
-- ============================================================================

BEGIN;

CREATE TABLE IF NOT EXISTS lawd_sido_remap (
  old_emd8 char(8) PRIMARY KEY,
  new_emd8 char(8) NOT NULL,
  old_name text   NOT NULL,
  new_name text   NOT NULL,
  n_rows   bigint NOT NULL,          -- Phase 1 이후 address 행수(해당 읍면동 8자리)
  src      text   NOT NULL           -- 'lawd_dong' | 'admin_boundary' — 코드 출처
);

CREATE TABLE IF NOT EXISTS lawd_ri_remap_exception (
  old_bcode char(10) PRIMARY KEY,   -- 46/29 체계 10자리
  new_bcode char(10) NOT NULL,      -- 12 체계 10자리
  ri        text     NOT NULL,
  note      text
);

-- ── lawd_sido_remap (623행) ────────────────────────────────────────────────

-- ── lawd_ri_remap_exception (4행) ──────────────────────────────────────────

COMMIT;

-- ── 적재 후 자가검증 (기대: 623 / 4) ──────────────────────────────────────
--   SELECT count(*) FROM lawd_sido_remap;            -->  623
--   SELECT count(*) FROM lawd_ri_remap_exception;    -->    4
--   SELECT src, count(*) FROM lawd_sido_remap GROUP BY 1;
--        -->  admin_boundary 1 / lawd_dong 622
